-- Data/Restock.lua (#14), generated by Tools/gen_restock.py: food and water
-- told apart by what they restore (alcohol out, the Manna Biscuit both), the
-- value ranking the classic vendor lines in level order, bind on pickup and
-- conjured flagged, ammo by kind, the reagents per class from the allowlist,
-- and every reagent spell's ranks known (the class trees' or the poisons').
GlassPearls = {}
dofile("Data/Restock.lua")
dofile("Data/SpellRanks.lua")
local D = GlassPearls.RestockData
dofile("tests/harness.lua")

check(type(D.build) == "string" and D.build:match("^%d+%.%d+%.%d+%.%d+$") ~= nil, "a build (" .. tostring(D.build) .. ")")
eq(D.drink[1708] and D.drink[1708].level, 25, "Sweet Nectar is water, level 25")
eq(D.drink[159] and D.drink[159].value, 151, "  Refreshing Spring Water restores 151 (its tooltip)")
check(D.food[2287] ~= nil and D.drink[2287] == nil, "Haunch of Meat is food, not water")
check(D.drink[19222] == nil and D.food[19222] == nil, "Cheap Beer is neither")
check(D.food[19301] and D.drink[19301] and D.food[19301].bop and D.drink[19301].bop, "the Alterac Manna Biscuit is both, bind on pickup")
check(D.drink[287964] and D.drink[287964].bop and D.drink[287964].level == 1, "Forever's level-1 Morning Glory Dew is bind on pickup")
check(D.drink[5350] and D.drink[5350].conjured, "Conjured Water is conjured")
check(not D.drink[159].bop and not D.drink[159].conjured, "  Refreshing Spring Water is neither")

local function rising(tbl, ids, what)
    for i = 2, #ids do
        local a, b = tbl[ids[i - 1]], tbl[ids[i]]
        if not (a and b and b.value > a.value and b.level > a.level) then
            return check(false, what .. ": " .. ids[i - 1] .. " then " .. ids[i])
        end
    end
    check(true, what .. " rises in value with the level")
end
rising(D.drink, { 159, 1179, 1205, 1708, 1645, 8766 }, "the vendor water line")
rising(D.food, { 4540, 4541, 4542, 4544, 4601, 8950 }, "the vendor bread line")
rising(D.food, { 117, 2287, 3770, 3771, 4599, 8952 }, "the vendor meat line")

eq(D.ammo[2512] and D.ammo[2512].kind, 2, "Rough Arrow: an arrow")
eq(D.ammo[11284] and D.ammo[11284].kind, 3, "Accurate Slugs: bullets")
eq(D.ammo[11285] and D.ammo[11285].level, 40, "Jagged Arrow: level 40")

check(D.reagents.MAGE and D.reagents.MAGE[17031] ~= nil, "a mage: Rune of Teleportation")
check(D.reagents.PRIEST[17056] and D.reagents.MAGE[17056], "Light Feather for both the priest and the mage")
check(D.reagents.WARRIOR == nil and D.reagents.HUNTER == nil, "warriors and hunters have none")
check(D.reagents.WARLOCK[6265] == nil, "the Soul Shard isn't on the allowlist")
eq(D.targets[21177], 100, "Symbol of Kings: 100 by default")
local listed = 0
for cls, items in pairs(D.reagents) do
    for item, spells in pairs(items) do
        listed = listed + 1
        if not (D.targets[item] and #spells > 0) then check(false, cls .. " " .. item .. ": a target and its spells") end
    end
end
check(listed > 0, "every reagent has a target and the spells that consume it")

eq(table.concat(D.higher[8681] or {}, ","), "8687,8691,11341,11342,11343", "Instant Poison: five higher ranks")
eq(D.higher[11343] and #D.higher[11343], 0, "  Instant Poison VI: the highest")
eq(table.concat(D.higher[458822] or {}, ","), "1214168", "Occult Poison I: then II (the numeral in the name)")
local unranked = {}
for _, spells in pairs(D.reagents.ROGUE) do
    for _, sid in ipairs(spells) do
        if not (D.higher[sid] or GlassPearls.SpellRankData.ranks[sid]) then unranked[#unranked + 1] = sid end
    end
end
eq(table.concat(unranked, ","), "", "every rogue reagent spell has its ranks (poisons here, Vanish in SpellRanks)")

done("test_restock_data")
